import mapboxgl from "mapbox-gl";
import React, { ReactNode, useEffect, useRef } from "react";

// //Parameters
// interface Props{
//     dataSet: [],
//     key: String,
//     latKey: String,
//     lngKey: String
// }

function HeatMap(dataset, key, latKey, lngKey){
  //MLAB API KEY
  mapboxgl.accessToken = 'pk.eyJ1IjoiZWxvdXciLCJhIjoiY20xMG5zYXN0MDdhcTJycjVoYXg3Y2VrbCJ9.m9NoEyiaJx-A2AXDHIR6Ew';

  //MAP PARAMETERS
  const map = useRef(null);
  const mapContainer = useRef(null);

  useEffect(()=>{

    map.current = new mapboxgl.Map({
      container: 'map',
      style: 'mapbox://styles/elouw/cm16f1zn801zd01o3hiikhhwt',
      center: [20,9],
      zoom:2
    })
  })

  return(
    <div id='map'/>
  )


}

export default HeatMap;
